// Nueve voces, siete estados de ánimo y cinco conflictos: 315 situaciones con elección.
export const EMOTIONS=['happy','angry','worried','proud','surprised','disappointed','determined'];
const MOOD={
 president:['Hoy hasta los sondeos sonríen. No lo jodas.','Director, he vendido los retrasos como una redistribución del tiempo libre. No me obligues a defender otra gilipollez.','Como esto reviente, no pienso salir yo en la foto.','He vuelto a demostrar que soy imprescindible. De nada.','¿Eso lo habéis conseguido sin una comisión? Me dejas tieso.','Confié en ti. Tampoco era mi primera mala decisión.','Vamos a sacarlo adelante aunque tenga que arrastrar a medio gabinete.'],
 minister:['Mira qué bien: una mañana sin ruedas de prensa de mierda.','¡Estoy hasta el moño de inaugurar tus excusas!','Me están llamando de Moncloa. Coge tú, valiente.','Esto lo he peleado yo mientras tú calentabas la silla.','No me jodas, ¿ha salido a la primera?','Tanto plan estratégico para acabar haciendo el canelo.','Se acabó marear expedientes. Hoy se firma y se trabaja.'],
 successor:['Hoy el tren corre más que mis respuestas en redes.','¡El siguiente que diga incidencia puntual se va andando!','Como esto se filtre, mañana desayuno titulares.','Me guardo esta victoria para restregársela al de enfrente.','¿Cómo que funciona? Mira otra vez, que me estás asustando.','No has gestionado una red: has aparcado problemas.','Vamos a poner orden. Y al que estorbe, que se aparte.'],
 treasury:['Soy Charo. Hoy no he traído la tijera grande. Aprovecha.','¡No sale, pedazo de manirroto! Sumar no es una ideología.','He visto la caja y se me ha cortado hasta el café.','He cuadrado tus cuentas. Un milagro y dos úlceras.','¿Dinero sin gastar? ¿Estás enfermo o se te ha roto el boli?','Te di un presupuesto, no una licencia para hacer el gilipollas.','Aquí se paga lo que toca. El confeti te lo compras tú.'],
 adif:['La cuadrilla ha terminado y nadie ha soltado una estupidez. Récord.','¡Baja al tajo a decir esa gilipollez sin zapatos de charol!','He visto el terreno. El terreno no ha leído tu calendario.','Esto está bien hecho. Puedes sacar la cinta sin hacer el ridículo.','¿El plano coincide con la obra? Hoy viene algo gordo.','Otra promesa encima del barro. Me cago en el folleto.','Las vías no se ponen con discursos. Dame medios y aparta.'],
 workshop:['Hoy los trenes suenan a tren, no a cubo de tornillos.','¡Ese cacharro no sale del taller, aunque te pongas como un energúmeno!','Ese ruido no me gusta un pelo. Y mira los que me quedan.','Lo hemos dejado fino. Ya puedes colgarte tú la medalla.','¿Repuestos antes de la avería? ¿Quién eres y qué has hecho con el director?','Te avisé. Pero claro, qué sabrá el del mono de grasa.','Se acabaron las chapuzas. O se arregla bien o no se mueve.'],
 riders:['Hoy he llegado a mi hora. Casi me da un pasmo.','¡Vete tú a esperar tres horas de pie, caradura!','No me prometas nada que luego tengo que explicárselo a mi jefe.','Os hemos hecho escuchar. A base de protestar, porque por educación ni caso.','¿Una solución de verdad? Espera, que le hago una foto.','Otra vez nos tomáis por gilipollas con billete.','No nos movemos de aquí hasta tener una respuesta decente.'],
 mayor:['Ha venido gente al pueblo y no era para cerrar algo.','¡Al pueblo no lo borras del mapa, listillo de despacho!','Como pierda este tren, el pueblo se me queda sin la poca vida que tiene.','Nos llamaban cuatro gatos. Pues los gatos ya tienen estación.','¿Vienes sin fotógrafo? Entonces igual hasta trabajas.','Nos prometiste futuro. Nos has dejado una marquesina y dos goteras.','Yo de aquí no me voy. Trae una silla, que vas a necesitarla.'],
 rival:['Qué gusto da ver cómo trabajas para mi cuenta de resultados.','¡Eso es competencia desleal! Lo mío era espíritu emprendedor.','Me has hecho mirar las cuentas dos veces. Cabronazo, casi te respeto.','He vendido hasta el asiento del conductor. Aprende, figura.','¿Has aprendido a competir? Vaya putada para mis previsiones.','Esperaba más de ti. Bueno, tampoco muchísimo.','Voy a por tus viajeros. Tú sigue redactando memorias.']};
const TOPICS=['El turno imposible','Billetes de saldo','Tornillos o titulares','El andén olvidado','El invento del mes'];
const LINES={
 president:['Quiero más salidas en hora punta. Y maquinistas, no asesores fingiendo conducir.','Lowgo se está llevando la foto. Elige si peleamos el precio o protegemos la caja.','No puedo inaugurar un tren que se queda tirado antes del primer canapé.','En esa comarca también hay urnas. Pon servicios antes de que vayan a votar en autobús.','Necesito una mejora que funcione antes de ponerle mi nombre.'],
 minister:['La nueva oferta necesita turnos. No pienso explicar que vendimos asientos sin conductor.','Bajar precios queda estupendo hasta que Charo te tira la calculadora a la cabeza.','El taller pide una revisión extra. El tren no se arregla por real decreto.','Podemos reforzar la atención de esa estación o mandar otro cartel. Adivina cuál molesta menos.','Los técnicos tienen un piloto listo. Esta vez no es un primo con una presentación.'],
 successor:['El horario está inflado. O pagamos refuerzos o dejamos de vender humo en ventanilla.','Rossa ha anunciado promoción. Como respondas con una nota de prensa, te la comes.','Otro vídeo del aire acondicionado muerto y nos conocen hasta en Saturno.','El alcalde amenaza con plantarse en el ministerio. Y ese no se va con una pegatina.','Quiero datos de verdad. La hoja de cálculo de tu cuñado cuenta como arma, no como herramienta.'],
 treasury:['Las horas extra no se pagan con entusiasmo. Saca la cartera o ajusta la oferta.','Cada descuento tiene que salir de algún sitio. A ser posible, no de mi paciencia.','La revisión cuesta menos que el rescate, lumbreras. Pero hay que pagarla hoy.','Ese pueblo necesita atención, no otra escultura delante del apeadero.','El piloto tiene presupuesto. Si lo conviertes en un agujero, te meto dentro.'],
 adif:['Sin cuadrilla de guardia, la incidencia de las seis la arregla el Espíritu Santo.','Si llenas el tren de ofertas y no refuerzas el andén, el atasco te lo comes tú.','Puedo inspeccionar la vía ahora o escuchar después que nadie lo había previsto.','La estación necesita acceso y personal. Las palomas no informan de las salidas.','Tenemos sensores para detectar fallos. Detectar gilipolleces aún se hace a mano.'],
 workshop:['Necesito manos en el turno de noche. Los trenes no se revisan con besos.','Los billetes baratos llenan los coches y vacían el almacén de repuestos. Haz números.','O cambiamos la pieza ahora o la pieza decide dónde termina el viaje.','El material de reserva también llega a provincias. No todo va a ser mimar al AVE de la foto.','La diagnosis nueva ve la avería antes que tu contable. Déjala probar.'],
 riders:['El primer tren nos deja tirados si no hay relevo. No somos figurantes de tu horario.','El precio de ayer no se parece al de hoy. ¿Vendéis billetes o apuestas?','Un baño averiado no es una experiencia de viaje. Es una puta vergüenza.','La estación está vacía de personal. Para hablar con una pared me quedo en casa.','Si la aplicación vuelve a perder el billete, os llevo la impresora al despacho.'],
 mayor:['El tren de primera hora es el que lleva a la gente al trabajo, no el de tu visita oficial.','Un billete de ida cuesta una compra semanal. Luego te extraña que no suba nadie.','Aquí también se estropean trenes. Manda mantenimiento, no un ramo de disculpas.','Quiero atención en la estación. Y no, el bar de mi cuñado no es un punto de información.','Si el sistema funciona aquí, funciona en cualquier sitio. No tenemos cobertura ni para discutir.'],
 rival:['Refuerza turnos, hombre. Así mis conductores dejan de recoger a tus viajeros abandonados.','He puesto una oferta obscena. Responde o sigue regalándome clientes, fenómeno.','Cada avería tuya me paga una rueda. ¿Seguro que quieres ahorrar en esa pieza?','Donde tú ves cuatro vecinos, yo veo cuatro billetes. Por eso me llaman empresario.','Si tú no pruebas esa mejora, la pruebo yo. Y luego te cobro por explicártela.']};
const OPTIONS=[
 [{label:'Pagar refuerzos este mes',effects:{cash:-1.2,satisfaction:2},group:'staff',trust:4},{label:'Ajustar turnos sin refuerzo',effects:{reputation:-1},group:'staff',trust:-3}],
 [{label:'Campaña de descuentos',effects:{cash:-1.5,satisfaction:3},flag:'hype',months:3,group:'riders',trust:3},{label:'Proteger el margen',effects:{cash:.3,satisfaction:-1},group:'treasury',trust:2}],
 [{label:'Revisión extraordinaria',effects:{cash:-2,reputation:1},flag:'fleetcare',group:'staff',trust:3},{label:'Seguir con el plan previsto',effects:{satisfaction:-1},group:'riders',trust:-2}],
 [{label:'Refuerzo de atención local',effects:{cash:-1,satisfaction:2},group:'territory',trust:5},{label:'Atención centralizada',effects:{reputation:-1},group:'territory',trust:-4}],
 [{label:'Financiar el piloto',effects:{cash:-1.8,reputation:2},flag:'hype',months:2,group:'government',trust:3},{label:'Pedir otra evaluación',effects:{},group:'government',trust:-2}]
];
export const ENCOUNTERS=Object.keys(MOOD).flatMap(person=>EMOTIONS.flatMap((mood,m)=>TOPICS.map((title,k)=>({id:`scene-${person}-${mood}-${k}`,person,mood,title,body:MOOD[person][m]+' '+LINES[person][k],topic:k,choices:OPTIONS[k].map(c=>({...c,detail:[c.effects.cash?`${c.effects.cash>0?'+':''}${c.effects.cash} M€`:'Sin desembolso',c.effects.satisfaction?`${c.effects.satisfaction>0?'+':''}${c.effects.satisfaction} satisfacción`:'',c.effects.reputation?`${c.effects.reputation>0?'+':''}${c.effects.reputation} reputación`:'',`${c.trust>0?'+':''}${c.trust} confianza`,c.flag==='fleetcare'?'Revisión de la flota':''].filter(Boolean).join(' · '),effects:{...c.effects}})),tycoon:true}))));
export const ENCOUNTER=Object.fromEntries(ENCOUNTERS.map(x=>[x.id,x]));
